1	export type Cell = [number, number];
2	
3	const keyOf = ([x, y]: Cell): string => `${x},${y}`;
4	
5	const neighborsOf = ([x, y]: Cell): Cell[] => [
6	  [x - 1, y - 1],
7	  [x, y - 1],
8	  [x + 1, y - 1],
9	  [x - 1, y],
10	  [x + 1, y],
11	  [x - 1, y + 1],
12	  [x, y + 1],
13	  [x + 1, y + 1],
14	];
15	
16	const survives = (liveNeighbors: number): boolean =>
17	  liveNeighbors === 2 || liveNeighbors === 3;
18	
19	const isBorn = (liveNeighbors: number): boolean => liveNeighbors === 3;
20	
21	export function nextGeneration(liveCells: Cell[]): Cell[] {
22	  const living = new Set(liveCells.map(keyOf));
23	
24	  const liveNeighborCount = (cell: Cell): number =>
25	    neighborsOf(cell).filter((neighbor) => living.has(keyOf(neighbor))).length;
26	
27	  const candidates = new Map<string, Cell>();
28	  for (const cell of liveCells) {
29	    candidates.set(keyOf(cell), cell);
30	    for (const neighbor of neighborsOf(cell)) {
31	      candidates.set(keyOf(neighbor), neighbor);
32	    }
33	  }
34	
35	  const nextLiveCells: Cell[] = [];
36	  for (const [cellKey, cell] of candidates) {
37	    const liveNeighbors = liveNeighborCount(cell);
38	    const livesOn = living.has(cellKey)
39	      ? survives(liveNeighbors)
40	      : isBorn(liveNeighbors);
41	    if (livesOn) {
42	      nextLiveCells.push(cell);
43	    }
44	  }
45	
46	  return nextLiveCells;
47	}
