// Rule 1: a live cell with fewer than two live neighbors dies.
const diesOfUnderpopulation = (liveNeighbors: number): boolean =>
  liveNeighbors < 2;

// Rule 3: a live cell with more than three live neighbors dies.
const diesOfOverpopulation = (liveNeighbors: number): boolean =>
  liveNeighbors > 3;

// Rule 2: a live cell with two or three live neighbors lives on.
const survives = (liveNeighbors: number): boolean =>
  !diesOfUnderpopulation(liveNeighbors) &&
  !diesOfOverpopulation(liveNeighbors);

// Rule 4: a dead cell with exactly three live neighbors becomes alive.
const isBorn = (liveNeighbors: number): boolean => liveNeighbors === 3;
